#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
ENV_FILE=".env.local"
PROJECT_NAME="business-wiki-agent"

# push_vercel_env NAME VALUE stores a sensitive env var on the linked Vercel
# project for every environment. Non-fatal: records a to-do on failure.
push_vercel_env() {
  local name="$1" value="$2"
  if printf '%s' "$value" | vercel env add "$name" production,preview,development \
       --sensitive --force --yes >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel env %s (production, preview, development)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name (run: vercel env add $name production,preview,development --sensitive)")
    warn "couldn't set Vercel env $name; add it later from the dashboard or CLI"
  fi
}

banner "Dev environment and credentials for $PROJECT_NAME"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Toolchain check"
say "Eve needs Node 24 and the Vercel CLI. Both were installed by the agent; this confirms them."
if ! command -v vercel >/dev/null 2>&1 || [[ "$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)" -lt 24 ]]; then
  export NVM_DIR="${NVM_DIR:-$HOME/.config/nvm}"
  # shellcheck disable=SC1091
  [[ -s "$NVM_DIR/nvm.sh" ]] && . "$NVM_DIR/nvm.sh" && nvm use default >/dev/null 2>&1 || true
fi
NODE_MAJOR="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"
if [[ "$NODE_MAJOR" -ge 24 ]]; then
  say "node $(node --version) ✓"
else
  warn "node is $(node --version 2>/dev/null || echo missing); run: nvm install 24 && nvm alias default 24, then re-run this wizard"
  exit 1
fi
if command -v vercel >/dev/null 2>&1; then
  say "$(vercel --version 2>/dev/null | head -1) ✓"
else
  warn "vercel CLI missing; run: npm install -g vercel@latest, then re-run"
  exit 1
fi
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 && say "gh logged in ✓" || note "gh not logged in (only needed for issue tracking, not for this wizard)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Vercel: sign in"
say "Eve deploys to Vercel and bills model calls through Vercel AI Gateway, so one Vercel account covers both."
if vercel whoami >/dev/null 2>&1; then
  say "Already signed in as $(vercel whoami 2>/dev/null | tail -1) ✓"
else
  step "If you have no Vercel account yet, create one (Hobby plan is enough) in the browser that opens."
  step "Then come back here: 'vercel login' will open a browser confirmation."
  open_url "https://vercel.com/signup"
  pause "Press Enter to run 'vercel login'"
  vercel login
  say "Signed in as $(vercel whoami 2>/dev/null | tail -1) ✓"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Vercel: create and link the project"
say "This links the repo to a Vercel project named '$PROJECT_NAME' (created if it doesn't exist)."
say "The link lives in .vercel/ (gitignored). 'eve deploy' and 'vercel env' use it."
if [[ -f .vercel/project.json ]]; then
  say "Already linked: $(cat .vercel/project.json) ✓"
  confirm "Re-link anyway?" && vercel link --project "$PROJECT_NAME"
else
  step "Answer the prompts: set up this directory → yes; scope → your personal account; link to existing → No unless you already made one."
  pause "Press Enter to run 'vercel link'"
  vercel link --project "$PROJECT_NAME"
fi
[[ -f .vercel/project.json ]] || { warn ".vercel/project.json not found; linking failed. Fix and re-run."; exit 1; }
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Vercel AI Gateway: API key"
say "One Gateway key serves the agent model (openai/gpt-5-mini) and the eval judge."
say "It never expires unless revoked, so it beats the 12-hour OIDC token for a 3-day build."
open_url "https://vercel.com/dashboard"
step "In the top navigation pick 'AI Gateway', then the 'API Keys' tab."
step "Click 'Create Key', name it '$PROJECT_NAME', create, and copy the key (shown once)."
note "If AI Gateway asks you to add credit, the free monthly allowance on Hobby is enough to start; add \$5 only if evals hit limits."
ask_secret AI_GATEWAY_API_KEY "Paste the AI Gateway API key:"
write_env AI_GATEWAY_API_KEY "$AI_GATEWAY_API_KEY"
push_vercel_env AI_GATEWAY_API_KEY "$AI_GATEWAY_API_KEY"
if curl -fsS -m 15 -H "Authorization: Bearer $AI_GATEWAY_API_KEY" https://ai-gateway.vercel.sh/v1/models >/dev/null 2>&1; then
  say "Gateway key accepted by https://ai-gateway.vercel.sh ✓"
else
  warn "Gateway did not accept the key (or the check endpoint moved). Re-check the key before running evals."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "LangSmith: API key and tracing project"
say "Reviewers live in LangSmith; Eve traces are exported there over OpenTelemetry."
say "The Developer plan is free (1 seat, 14-day retention), so share trace links late."
open_url "https://smith.langchain.com"
step "Sign up or log in (Developer plan)."
step "Open Settings (gear icon, bottom-left) → 'API Keys' → 'Create API Key'. A Personal Access Token is fine. Copy it."
ask_secret LANGSMITH_API_KEY "Paste the LangSmith API key:"
step "Now 'Tracing Projects' (left nav) → '+ New Project' → name it '$PROJECT_NAME' → Create."
ask LANGSMITH_PROJECT "Tracing project name [Enter for $PROJECT_NAME]:" || true
: "${LANGSMITH_PROJECT:=$PROJECT_NAME}"
write_env LANGSMITH_API_KEY "$LANGSMITH_API_KEY"
write_env LANGSMITH_PROJECT "$LANGSMITH_PROJECT"
push_vercel_env LANGSMITH_API_KEY "$LANGSMITH_API_KEY"
push_vercel_env LANGSMITH_PROJECT "$LANGSMITH_PROJECT"
if curl -fsS -m 15 -H "x-api-key: $LANGSMITH_API_KEY" "https://api.smith.langchain.com/api/v1/sessions?limit=1" >/dev/null 2>&1; then
  say "LangSmith key accepted ✓"
else
  warn "LangSmith did not accept the key (or you are on a regional host: eu./apac./aws.api.smith.langchain.com). Re-check before wiring tracing."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Braintrust (optional fallback trace destination)"
say "The map keeps Braintrust as the fallback if LangSmith export eats more than half a day."
say "Eve has a native Braintrust integration; grabbing the key now costs two minutes."
if confirm "Set up Braintrust now?"; then
  open_url "https://www.braintrust.dev/app"
  step "Sign up or log in, create an organization if asked."
  step "Settings → 'API Keys' → 'Create API key' → copy it."
  ask_secret BRAINTRUST_API_KEY "Paste the Braintrust API key:"
  write_env BRAINTRUST_API_KEY "$BRAINTRUST_API_KEY"
  push_vercel_env BRAINTRUST_API_KEY "$BRAINTRUST_API_KEY"
else
  note "Skipped. Re-run this wizard any time; earlier values are kept."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Verify"
say "Local secrets are in $ENV_FILE (gitignored). Vercel project env should list the same names:"
printf '\n'
vercel env ls 2>/dev/null | sed 's/^/    /' || warn "vercel env ls failed; check the project's Environment Variables tab in the dashboard"
printf '\n'
say "Not done here on purpose: a Vercel Blob store (waits on the 'Wiki persistence and deployment shape' ticket)."
pause

finish
}

run_wizard "$@"; exit
